<?php $this->layout('layouts/admin', ['title' => 'Liên hệ', 'pageTitle' => 'Yêu cầu liên hệ', 'activeMenu' => 'contact']) ?>
<?php $this->start('page') ?>
<div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Người gửi</th><th>Kênh</th><th>Nội dung</th><th>Trạng thái</th><th>Ngày gửi</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach ($contacts as $contact) : ?><tr><td>#<?= (int)$contact['contactId'] ?></td><td><strong><?= $this->e($contact['fullName']) ?></strong><small class="d-block text-secondary"><?= $this->e($contact['email'] ?: $contact['phoneNumber']) ?></small></td><td><?= $this->e($contact['contactMethod']) ?></td><td><span class="d-inline-block text-truncate" style="max-width:300px"><?= $this->e($contact['message']) ?></span></td><td><span class="badge text-bg-<?= $contact['status']==='RESOLVED'?'success':'warning' ?>"><?= $this->e(contact_status_label($contact['status'])) ?></span></td><td><?= date('d/m/Y H:i',strtotime($contact['createdAt'])) ?></td><td><div class="d-flex justify-content-end gap-1"><a href="/admin/contacts/show/<?= (int)$contact['contactId'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-eye"></i></a><?php if($contact['status']!=='RESOLVED'):?><form action="/admin/contacts/resolve/<?= (int)$contact['contactId'] ?>" method="POST"><?= csrf_field() ?><button class="btn btn-sm btn-outline-success"><i class="bi bi-check2"></i></button></form><?php endif;?><form action="/admin/contacts/delete/<?= (int)$contact['contactId'] ?>" method="POST" onsubmit="return confirm('Xóa yêu cầu này?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$contacts):?><tr><td colspan="7" class="text-center text-secondary py-5">Chưa có yêu cầu liên hệ.</td></tr><?php endif;?></tbody></table></div></div>
<?php $this->stop() ?>
